projectFiles.src/books.js:
const books = [];
let nextId = 1;

export function listBooks() {
  return books;
}

export function addBook({ title, author }) {
  if (!title) throw new Error("title is required");
  const book = { id: nextId++, title, author: author ?? "" };
  books.push(book);
  return book;
}

projectFiles.src/server.js:
import { createServer } from "node:http";
import { listBooks, addBook } from "./books.js";

const server = createServer(async (req, res) => {
  if (req.method === "GET" && req.url === "/books") {
    res.writeHead(200, { "content-type": "application/json" });
    res.end(JSON.stringify(listBooks()));
    return;
  }
  if (req.method === "POST" && req.url === "/books") {
    let body = "";
    for await (const chunk of req) body += chunk;
    const book = addBook(JSON.parse(body));
    res.writeHead(201, { "content-type": "application/json" });
    res.end(JSON.stringify(book));
    return;
  }
  res.writeHead(404);
  res.end();
});

server.listen(process.env.PORT ?? 3000);

projectFiles.test/books.test.js:
import { test } from "node:test";
import assert from "node:assert/strict";
import { addBook, listBooks } from "../src/books.js";

test("addBook stores a book with an id", () => {
  const book = addBook({ title: "Holes", author: "Louis Sachar" });
  assert.equal(book.id, 1);
  assert.equal(listBooks().length, 1);
});

